const main=document.querySelector('#main');
const products={testamente:{name:'Testamente',price:595,description:'Sätt ord på dina önskemål för framtiden. Vi hjälper dig att komma igång, en fråga i taget.'},aktenskapsforord:{name:'Äktenskapsförord',price:595,description:'Prata om er ekonomi och beskriv hur ni vill ha det. Med ett tydligt upplägg för er båda.'}};
let state={product:null,step:0,answers:{},paid:false};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const lifeStages={home:{label:'Första gemensamma hemmet',image:'first-home-photo.jpg',title:'Ett nytt hem.<br><em>Ett nytt kapitel.</em>',copy:'När ni bygger ett liv tillsammans finns det mycket att prata om. Börja med era önskemål för ekonomin och framtiden.'},family:{label:'Familjeliv',image:'family-photo.jpg',title:'Ta hand om det<br>som <em>betyder mest.</em>',copy:'Mitt i vardagen finns det beslut som förtjänar lite extra omtanke. Samla dina önskemål med frågor som är lätta att förstå.'},future:{label:'Planera framtiden',image:'future-photo.jpg',title:'Era önskemål.<br><em>En tydligare framtid.</em>',copy:'Ge det viktiga en stund. Beskriv vad du vill för framtiden och se dina önskemål samlade, ett steg i taget.'}};
let selectedLifeStage='family';
function chooseLifeStage(key){if(!Object.hasOwn(lifeStages,key))throw new Error('Ogiltigt livsskede');selectedLifeStage=key;const s=lifeStages[key];const hero=document.querySelector('.hero');if(!hero)return;hero.style.setProperty('--hero-image',`url('${s.image}')`);document.querySelector('#life-title').innerHTML=s.title;document.querySelector('#life-copy').textContent=s.copy;document.querySelectorAll('[data-life-stage]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lifeStage===key)));}
function home(){const s=lifeStages[selectedLifeStage];main.innerHTML=`<div class="container fade"><div class="life-selector" role="group" aria-label="Välj ditt livsskede"><span>Livet förändras. Vad passar dig?</span><div>${Object.entries(lifeStages).map(([key,item])=>`<button type="button" data-life-stage="${key}" aria-pressed="${selectedLifeStage===key}" aria-controls="life-title life-copy">${item.label}</button>`).join('')}</div></div><section class="hero" style="--hero-image:url('${s.image}')"><div><div class="eyebrow">Juridik för livet</div><h1 id="life-title">${s.title}</h1><p id="life-copy">${s.copy}</p><a class="button" href="#products">Hitta ditt dokument</a><p class="micro">Testamente och äktenskapsförord · 595 kr per dokument</p></div></section><div class="principles"><span>Begripliga frågor</span><span>595 kr per dokument inkl. moms</span><span>Ändra innan du är klar</span></div><section class="block" id="products"><div class="section-heading"><div><div class="eyebrow">Två dokument. Ett tydligt styckpris.</div><h2>Vad vill du ta hand om?</h2></div><div class="product-intro"><strong>595 kr per dokument</strong><span>Inklusive moms. Samma pris för båda.</span><p>Välj testamente eller äktenskapsförord. I denna demo betalar du 0 kr.</p></div></div><div class="cards">${Object.entries(products).map(([key,p],i)=>`<article class="card"><div class="card-icon" aria-hidden="true">${i?'§':'✦'}</div><h3>${p.name}</h3><p>${p.description}</p><div class="card-bottom"><div class="price">${p.price} kr<small>per dokument · inklusive moms</small></div><a class="button" href="#flow/${key}/0">Börja med ${i?'äktenskapsförord':'testamente'}</a></div></article>`).join('')}</div><p class="micro">Priset visar tjänstens tänkta styckpris. Detta är en demonstration: ingen debitering sker och utkasten ska inte skrivas under.</p></section></div><div class="how-wrap" id="how"><section class="block container"><div class="eyebrow">En tydlig väg framåt</div><h2>Från fundering till överblick.</h2><div class="steps"><div><span class="step-num">01</span><h3>Berätta om din situation</h3><p>Svara på enkla frågor. Vi förklarar vad vi frågar efter och varför.</p></div><div><span class="step-num">02</span><h3>Se dina önskemål samlade</h3><p>Kontrollera svaren och läs ditt dokumentutkast. Gå tillbaka när du vill ändra något.</p></div><div><span class="step-num">03</span><h3>Prova att slutföra</h3><p>Testa köpflödet och hämta ett tydligt märkt demoutkast. Ingen debitering sker.</p></div></div></section></div><section class="block container" id="faq"><div class="faq"><div class="eyebrow">Dina frågor</div><h2>Det du vill veta innan.</h2><details><summary>Vad ingår i priset på 595 kr?</summary><p>595 kr inklusive moms är det tänkta styckpriset för ett testamente eller ett äktenskapsförord. Här kan du prova frågorna, ändra dina svar och se ett utkast. Demoköpet kostar 0 kr. Vad som ingår i en färdig juridisk leverans behöver beskrivas före en riktig beställning; denna demo utlovar inte individuell granskning, rådgivning eller registrering.</p></details><details><summary>Vilket dokument passar det jag vill göra?</summary><p>Ett testamente handlar om hur du vill att din kvarlåtenskap ska fördelas efter din död, inom de gränser lagen sätter. Ett äktenskapsförord låter makar eller blivande makar bestämma att egendom ska vara enskild. De fyller olika syften och ersätter inte varandra. Läs <a href="https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/arvdabalk-1958637_sfs-1958-637/" target="_blank" rel="noopener">ärvdabalken</a> och <a href="https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/aktenskapsbalk-1987230_sfs-1987-230/" target="_blank" rel="noopener">äktenskapsbalken, 7 kap. 3 §</a>.</p></details><details><summary>Passar dokumenten när vi köper vår första bostad?</summary><p>Livsskedesbilderna är inspiration. Livsklart visar här endast testamente och äktenskapsförord. Ett äktenskapsförord är till för makar eller blivande makar. Demon erbjuder inte samboavtal eller köpekontrakt och avgör inte vilka avtal ett bostadsköp kräver.</p></details><details><summary>Kan jag ändra mig innan jag är klar?</summary><p>Ja. Du kan gå tillbaka i frågorna och välja Ändra i sammanfattningen. Utkastet uppdateras efter dina svar. Kontrollera särskilt namn, personer och vilken egendom du beskrivit innan du går vidare.</p></details><details><summary>Måste dokumentet skrivas under eller registreras?</summary><p>För ett vanligt testamente krävs en skriftlig handling och två vittnen. Du ska skriva under eller bekräfta din underskrift i bådas samtidiga närvaro, och vittnena ska skriva under. Lagen begränsar vilka som får vara vittnen. Ett äktenskapsförord ska vara skriftligt, daterat, undertecknat av båda och registreras hos Skatteverket. Läs <a href="https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/arvdabalk-1958637_sfs-1958-637/" target="_blank" rel="noopener">ärvdabalken, 10 kap. 1 och 4 §§</a> och <a href="https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/aktenskapsbalk-1987230_sfs-1987-230/" target="_blank" rel="noopener">äktenskapsbalken, 7 kap. 3 §</a>. Demoutkasten ska varken skrivas under eller registreras.</p></details><details><summary>Vad gör jag när jag har svarat på frågorna?</summary><p>Läs sammanfattningen, rätta det som behövs och prova demoköpet. Efteråt kan du hämta ett märkt textutkast. Det är ett underlag för att testa upplevelsen, inte en färdig juridisk handling. Inför faktisk användning behöver innehållet och din situation bedömas juridiskt.</p></details><details><summary>Finns det en jurist bakom Livsklart?</summary><p>Ja, det finns en jurist bakom tjänsten. Den här webbplatsen är fortfarande en mockup. Den visar inte att just dessa utkast är färdiggranskade eller att varje dokument får individuell granskning.</p></details><details class="demo-details"><summary>Om demonstrationen: betalning och uppgifter</summary><p>Ingen betalning eller beställning skickas. Använd påhittade uppgifter. Dina svar finns bara i minnet i den här fliken och försvinner när sidan laddas om. Du behöver inte ange kortuppgifter, BankID eller personnummer. Bilderna är licensierade stockfotografier och visar inte Livsklarts kunder.</p></details></div></section>`;document.querySelectorAll('[data-life-stage]').forEach(b=>b.onclick=()=>chooseLifeStage(b.dataset.lifeStage));}
function fields(){const a=state.answers;return state.product==='testamente'?[
{title:'Vem gäller testamentet?',intro:'Vi börjar med lite om dig. Använd gärna ett påhittat namn när du provar.',fields:[{key:'name',label:'Ditt namn',placeholder:'Till exempel Alex Andersson'},{key:'family',label:'Hur ser din situation ut?',type:'radio',options:['Jag är ensamstående','Jag är sambo','Jag är gift']},{key:'children',label:'Har du barn?',type:'radio',options:['Ja','Nej']}],help:'Din situation',hint:'Familjesituationen kan påverka hur ett riktigt testamente behöver utformas. Här samlar vi bara uppgifter för ett demoutkast.'},
{title:'Vem vill du ska få ta del?',intro:'Berätta vem eller vilka du vill nämna. I demon räcker en kort beskrivning.',fields:[{key:'beneficiary',label:'Namn på person eller organisation',placeholder:'Till exempel Kim Andersson'},{key:'wish',label:'Vad är ditt önskemål?',type:'textarea',placeholder:'Till exempel: Jag vill att Kim får min samling av böcker.'}],help:'Dina önskemål',hint:'Detta är ett sätt att prova tjänsten. Vi kontrollerar inte arvsrätt, laglott eller hur en fördelning fungerar juridiskt.'},
{title:'Finns det något mer du vill nämna?',intro:'Lägg till sådant du vill ta upp i ett framtida samtal om ditt dokument.',fields:[{key:'extra',label:'Övriga önskemål (valfritt)',type:'textarea',optional:true,placeholder:'Skriv ett önskemål eller lämna tomt.'}],help:'En sista avstämning',hint:'I nästa steg ser du alla svar samlade. Du kan ändra dem innan du provar köpet.'}
]:[
{title:'Vilka gäller dokumentet?',intro:'Berätta vilka ni är. Använd påhittade namn i demonstrationen.',fields:[{key:'name',label:'Ditt namn',placeholder:'Till exempel Alex Andersson'},{key:'partner',label:'Din partners namn',placeholder:'Till exempel Kim Andersson'},{key:'relationship',label:'Vad passar in på er?',type:'radio',options:['Vi är gifta','Vi planerar att gifta oss']}],help:'Ni och er situation',hint:'Demon visar ett exempel på hur uppgifter kan samlas in. Ingen bedömning av er juridiska situation görs.'},
{title:'Vad vill ni beskriva?',intro:'Välj ett utgångsläge för er diskussion och beskriv egendomen med egna ord.',fields:[{key:'scope',label:'Vad gäller ert önskemål?',type:'radio',options:['Viss egendom','All egendom']},{key:'property',label:'Beskriv egendomen och vem den tillhör',type:'textarea',placeholder:'Till exempel: Alex sparande på ett eget konto.'}],help:'En gemensam utgångspunkt',hint:'Demon visar hur ett upplägg kan se ut. Vi bedömer inte effekter vid bodelning eller om beskrivningen är tillräckligt tydlig.'},
{title:'Samla det sista ni vill ta upp',intro:'Finns det något ni vill förtydliga innan ni går vidare?',fields:[{key:'extra',label:'Övrigt att ta upp (valfritt)',type:'textarea',optional:true,placeholder:'Till exempel frågor om framtida sparande.'}],help:'Innan ni går vidare',hint:'Se era svar tillsammans i nästa steg. Detta utkast ska inte skrivas under eller skickas in för registrering.'}
];}
function field(f){const value=state.answers[f.key]||'';const hint=f.optional?'':'required';return `<div class="field">${f.type==='radio'?`<fieldset><legend>${f.label}</legend>${f.options.map((o,i)=>`<label class="option"><input type="radio" name="${f.key}" value="${esc(o)}" ${value===o?'checked':''} ${hint}>${o}</label>`).join('')}</fieldset>`:`<label for="${f.key}">${f.label}</label>${f.type==='textarea'?`<textarea id="${f.key}" name="${f.key}" rows="4" maxlength="1200" placeholder="${f.placeholder}" ${hint}>${esc(value)}</textarea>`:`<input id="${f.key}" name="${f.key}" maxlength="150" autocomplete="off" value="${esc(value)}" placeholder="${f.placeholder}" ${hint}>`}`}</div>`;}
function shell(content){const p=products[state.product];main.innerHTML=`<section class="flow fade"><div class="container"><div class="flow-top"><a href="#products">Alla dokument</a><span>${p.name} · ${p.price} kr <small>(exempelpris)</small></span></div><div class="progress" role="progressbar" aria-label="Framsteg" aria-valuemin="0" aria-valuemax="5" aria-valuenow="${Math.min(state.step+1,5)}"><div style="width:${Math.min((state.step+1)*20,100)}%"></div></div>${content}</div></section>`;}
function flow(){const steps=fields();if(state.step<3){const s=steps[state.step];shell(`<div class="flow-grid"><div class="form-card"><div class="eyebrow">Fråga ${state.step+1} av 3</div><h1>${s.title}</h1><p>${s.intro}</p><form id="questions">${s.fields.map(field).join('')}<p id="error" class="error" role="alert"></p><div class="actions"><button type="button" class="secondary" id="back">Tillbaka</button><button class="primary" type="submit">${state.step===2?'Se sammanfattning':'Fortsätt'}</button></div></form></div><aside class="aside"><h3>${s.help}</h3><p>${s.hint}</p><hr><p>Du behöver inte bli klar på en gång. Dina svar finns kvar när du går fram och tillbaka i flödet.</p><p class="notice">Använd påhittade uppgifter. Inget sparas efter att sidan laddats om.</p></aside></div>`);document.querySelector('#back').onclick=()=>go(state.step?state.step-1:'home');document.querySelector('#questions').onsubmit=e=>{e.preventDefault();saveForm();go(state.step+1)};document.querySelector('#questions').oninput=saveForm;}else if(state.step===3)review();else checkout();}
function saveForm(){const form=document.querySelector('#questions');if(!form)return;for(const f of fields()[state.step].fields){const v=new FormData(form).get(f.key);state.answers[f.key]=v?String(v).trim():'';}}
function go(step){location.hash=step==='home'?'products':`flow/${state.product}/${step}`;}
function documentText(){const a=state.answers;return `Livsklart\nDEMOUTKAST – INTE EN JURIDISK HANDLING\n${products[state.product].name}\n\n${state.product==='testamente'?`Namn: ${a.name}\nFamiljesituation: ${a.family}\nBarn: ${a.children}\nPerson eller organisation: ${a.beneficiary}\nÖnskemål: ${a.wish}`:`Parter: ${a.name} och ${a.partner}\nSituation: ${a.relationship}\nOmfattning: ${a.scope}\nBeskrivning: ${a.property}`}\n\nÖvrigt: ${a.extra||'Inga övriga önskemål angivna.'}\n\nDetta är en sammanställning av demosvar. Ingen juridisk dokumentgenerering eller granskning har genomförts. Ska inte skrivas under, användas eller registreras.`;}
function review(){shell(`<div class="flow-grid"><div class="form-card"><div class="eyebrow">Din överblick</div><h1>Så här har du svarat.</h1><p>Läs igenom i lugn och ro. Du kan ändra varje del.</p>${fields().map((s,i)=>`<div class="review-row"><div>${s.fields.map(f=>`<span>${f.label}</span><strong>${esc(state.answers[f.key]||'Inte angivet')}</strong>`).join('<br>')}</div><button class="text-button" data-edit="${i}">Ändra<span class="sr-only"> del ${i+1}</span></button></div>`).join('')}<div class="preview-document"><div class="watermark">DEMO · EJ FÖR UNDERSKRIFT</div><h3>Förhandsvisning: ${products[state.product].name}</h3><p>${esc(documentText())}</p></div><div class="actions"><button class="secondary" id="back">Tillbaka</button><button class="primary" id="next">Till demoköp</button></div></div><aside class="aside"><h3>Dina svar, samlade</h3><p>Förhandsvisningen visar hur ett utkast skulle kunna presenteras.</p><p class="notice">Detta är inte ett färdigt juridiskt dokument. Utkastet saknar juridisk granskning och formkrav för användning.</p></aside></div>`);document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>go(Number(b.dataset.edit)));document.querySelector('#back').onclick=()=>go(2);document.querySelector('#next').onclick=()=>go(4);}
function checkout(){const p=products[state.product];shell(`<div class="flow-grid"><div class="form-card"><div class="eyebrow">Sista steget · demonstration</div><h1>Prova att slutföra.</h1><p>Inga pengar dras. Du behöver inte ange kort, e-post eller personnummer.</p><div class="review-row"><strong>${p.name}</strong><strong>${p.price} kr</strong></div><div class="review-row"><span>Exempelpris inklusive moms</span><span>Simulerat köp</span></div><div class="review-row"><strong>Att betala i denna demo</strong><strong>0 kr</strong></div><form id="checkout"><div class="field"><label class="option"><input type="checkbox" required>Jag förstår att detta är en demonstration och att utkastet inte ska användas som juridisk handling.</label></div><div class="actions"><button type="button" class="secondary" id="back">Tillbaka</button><button class="primary" type="submit">Slutför demoköp · 0 kr</button></div></form></div><aside class="aside"><h3>Det här händer sedan</h3><ul><li>Du ser en simulerad bekräftelse.</li><li>Du kan hämta dina demosvar som textfil.</li><li>Inga pengar dras och ingen beställning skickas.</li></ul></aside></div>`);document.querySelector('#back').onclick=()=>go(3);document.querySelector('#checkout').onsubmit=e=>{e.preventDefault();state.paid=true;location.hash=`complete/${state.product}`};}
function complete(){main.innerHTML=`<section class="success fade"><div class="success-badge" aria-hidden="true">✓</div><div class="eyebrow">Demoköp slutfört</div><h1>Nu har du provat<br>hela vägen.</h1><p>Dina svar till ${products[state.product].name.toLowerCase()} är samlade. Inget köp har genomförts och inga pengar har dragits.</p><p class="notice">Utkastet är endast ett exempel. Det är inte juridiskt granskat och ska inte användas eller skrivas under.</p><div class="actions"><button class="primary" id="download">Hämta demoutkast (.txt)</button><a class="secondary" href="#flow/${state.product}/3">Se mina svar</a><a href="#products">Prova ett annat dokument</a></div></section>`;document.querySelector('#download').onclick=()=>{const url=URL.createObjectURL(new Blob([documentText()],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`livsklart-${state.product}-DEMOUTKAST.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};}
function route(){const parts=location.hash.slice(1).split('/');if(parts[0]==='flow'&&products[parts[1]]){if(state.product!==parts[1])state={product:parts[1],step:0,answers:{},paid:false};const n=Number(parts[2]);state.step=Number.isInteger(n)&&n>=0&&n<=4?n:0;for(let i=0;i<Math.min(state.step,3);i++){if(fields()[i].fields.some(f=>!f.optional&&!state.answers[f.key])){state.step=i;break}}flow();window.scrollTo(0,0);}else if(parts[0]==='complete'&&state.paid&&state.product===parts[1]){complete();window.scrollTo(0,0);}else if(parts[0]==='about'){main.innerHTML='<section class="container block"><div class="eyebrow">Om demonstrationen</div><h1>En första version att prova.</h1><p>Livsklart är här en webbmockup för att få feedback på språk, design och kundflöde. Priserna är exempel. Inga kundrecensioner, juristmeriter eller certifieringar påstås.</p><p>Svaren bearbetas enbart i flikens minne. Betalning, juridisk granskning och färdiga juridiska dokument ingår inte. Använd påhittade uppgifter.</p><a class="button" href="#products">Prova ett dokument</a></section>';window.scrollTo(0,0);}else{home();if(parts[0]&&document.getElementById(parts[0]))document.getElementById(parts[0]).scrollIntoView();else window.scrollTo(0,0)}}
window.addEventListener('hashchange',route);route();
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'start_document_demo',description:'Öppna första frågan i demonstrationen för valt dokument. Inget köp genomförs.',inputSchema:{type:'object',properties:{product:{type:'string',enum:['testamente','aktenskapsforord']}},required:['product'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!products[input.product])throw new Error('Ogiltigt dokumentval');location.hash=`flow/${input.product}/0`;route();return {product:state.product,step:state.step}}});}catch(e){console.info('WebMCP unavailable',e)}}
